@Override protected Void onExecute(Context context, Bundle args) {
  long id = args.getLong("id");
  long wakeup = args.getLong("wakeup");
  DB db = DB.getInstance(context);
  try {
    db.message().setMessageSnoozed(id, wakeup < 0 ? null : wakeup);
  } catch (IllegalArgumentException e) {
    // 记录参数无效的错误日志
    Log.e("onExecute", "Invalid argument: " + e.getMessage(), e);
    throw e; // 重新抛出异常以通知调用者
  } catch (SecurityException e) {
    // 记录权限不足的错误日志
    Log.e("onExecute", "Security exception: " + e.getMessage(), e);
    throw e; // 重新抛出异常以通知调用者
  }
  return null;
}
